    };
    node.ownerDocument.addEventListener("selectionchange", selection);
    const observer = new MutationObserver(() => {
      if (alive) finish();
    });
    observer.observe(node, {
      attributes: true,
      attributeFilter: ["class", "style", "hidden", "aria-disabled", "disabled"],
    });
