    };
    const run = (event: Event) => {
      if (!alive || ref.current !== node || event.target !== node || !lease?.current()) return;
      if (entry && node.contains(node.ownerDocument.activeElement)) settle();
      const current = lease;
      for (const animation of animations()) {
        if (handles.has(animation)) continue;
        handles.add(animation);
        void animation.finished.then(
          () => {
            if (!alive || ref.current !== node || !current.current()) return;
            handles.delete(animation);
            if (!handles.size) entry = false;
          },
          () => {},
        );
      }
    };
    const observer = new MutationObserver((records) => {
      if (!alive || ref.current !== node) return;
      revise(records.some((record) => record.attributeName === "data-closed" && record.oldValue !== null));
    });
    observer.observe(node, {
      attributes: true,
      attributeOldValue: true,
      attributeFilter: ["data-open", "data-closed", "data-ending-style"],
    });
    for (const type of ["focusin", "pointerdown", "click", "keydown", "beforematch"])
      node.addEventListener(type, settle, true);
    const selection = () => {
      const selected = node.ownerDocument.getSelection()?.anchorNode;
      if (alive && ref.current === node && selected && node.contains(selected)) settle();
    };
    node.ownerDocument.addEventListener("selectionchange", selection);
    node.addEventListener("transitionrun", run);
    revise();
    connection.current = {
      node,
      signature,
      dispose(retire = true) {
        alive = false;
        owner.dispose();
        if (retire) scope.transaction.close();
        observer.disconnect();
        node.ownerDocument.removeEventListener("selectionchange", selection);
        node.removeEventListener("transitionrun", run);
        for (const type of ["focusin", "pointerdown", "click", "keydown", "beforematch"])
          node.removeEventListener(type, settle, true);
        node.removeAttribute("data-cadence-entry-settled");
        if (surfaces.get(node) === properties) {
          surfaces.delete(node);
          publish(node);
        }
      },
    };
  });
  useInsertionEffect(
    () => () => {
      const old = connection.current;
      connection.current = null;
      old?.dispose();
    },
    [],
  );
  return (children: ReactNode) => <MotionPresentation scope={scope}>{children}</MotionPresentation>;
}

/** Explicit family props yield; opaque classes retain their ordinary cascade. */
export function hasCallerTransition(className: unknown, style: unknown) {
  return (
    (typeof className === "string" && /(?:^|[:\s])(?:transition|duration|delay|ease)(?:-|\s|$)/.test(className)) ||
    Boolean(
      style && typeof style === "object" && Object.keys(style).some((key) => /^(?:transition|animation)/.test(key)),
    )
  );
}

"use client";

import { type Ref, useCallback, useEffect, useInsertionEffect, useLayoutEffect, useRef } from "react";

export type MotionHostRef<T extends Element = Element> = {
  current: T | null;
  identity?: object;
  invalidate?: () => void;
};

/** Separate physical owner identity from the caller's React 19 ref registration. */
export function useMotionHostRef<T extends Element>(external?: Ref<T>) {
  const node = useRef<T | null>(null) as MotionHostRef<T>;
  const desired = useRef(external);
  const physical = useRef<{ element: T } | null>(null);
  const binding = useRef<{ element: T; source: Ref<T> | undefined; release(): void } | null>(null);
  const callerGeneration = useRef(0);
  useInsertionEffect(() => {
    desired.current = external;
  }, [external]);
  const disconnect = useCallback(() => {
    callerGeneration.current++;
    const old = binding.current;
    binding.current = null;
    node.identity = {};
    node.current = null;
    node.invalidate?.();
    old?.release();
  }, []);
  const connect = useCallback((lifetime: { element: T }) => {
    const epoch = ++callerGeneration.current;
    const old = binding.current;
    binding.current = null;
    old?.release();
    if (physical.current !== lifetime || callerGeneration.current !== epoch) return;
    const { element } = lifetime;
    const source = desired.current;
    let active = true,
      ready = false,
      cleaned = false;
    let cleanup: undefined | (() => void);
    const release = () => {
      if (!ready || cleaned) return;
      cleaned = true;
      if (typeof cleanup === "function") cleanup();
      else if (typeof source === "function") source(null);
      else if (
        source &&
        source.current === element &&
        (binding.current?.source !== source || binding.current.element !== element)
      )
        source.current = null;
    };
    const record = {
      element,
      source,
      release() {
        active = false;
        release();
      },
    };
    binding.current = record;
    try {
      if (typeof source === "function") {
        const returned = source(element);
        cleanup = typeof returned === "function" ? returned : undefined;
      } else if (source) source.current = element;
      ready = true;
      if (!active) release();
    } catch (error) {
      if (binding.current === record) {
        binding.current = null;
      }
      throw error;
    }
  }, []);
  const ref = useCallback(
    (element: T | null) => {
      const lifetime = element ? { element } : null;
      physical.current = lifetime;
      disconnect();
      if (lifetime && physical.current === lifetime) {
        node.identity = lifetime;
        node.current = element;
        connect(lifetime);
      }
      return () => {
        if (physical.current !== lifetime) return;
        physical.current = null;
        disconnect();
      };
    },
    [connect, disconnect],
  );
  const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
  // Motion keeps its physical ref stable when only the caller ref changes.
  // Rebind that caller before controller layout work, without remounting Motion.
  committed(() => {
    const lifetime = physical.current;
    if (lifetime && binding.current?.source !== external) connect(lifetime);
  }, [external, connect]);
  return { node, ref };
}

/** Explicit component identity, never displayName or caller-component inspection.
 * Membership layers are only offered by controls with a known plain native host. */
const controls = new WeakSet<object>();
export function registerGroupControl(control: object) {
  controls.add(control);
}
export function isGroupControl(control: unknown) {
  return (typeof control === "function" || (typeof control === "object" && control !== null)) && controls.has(control);
}

"use client";

import { bindMotionParameters, motionMilliseconds, presenceExit, presenceInline } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease } from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type InlinePresenceCommit = {
  present: boolean;
  enter: boolean;
  /** A committed replacement shares the existing opacity channel. */
  revision?: unknown;
  cm: CadenceMotion;
  complete?: () => void;
};

/** Opacity only, on the original retained host. Never writes a resting opacity. */
export function createInlinePresence(node: HTMLElement, transaction = createMotionTransaction()) {
  const owner = transaction.register(node);
  let current: InlinePresenceCommit | null = null;
  let lease: MotionLease | null = null;
  let animation: Animation | null = null;
  let alive = true;
  let blocked = false;
  let generation = 0;
  const cancel = () => {
    generation++;
    animation?.cancel();
    animation = null;
    lease?.cancel();
    lease = null;
  };
  const settle = () => {
    cancel();
    if (alive && current?.present === false) current.complete?.();
  };
  const callerOpacity = (css = node.ownerDocument.defaultView?.getComputedStyle(node)) => {
    if (!css) return false;
    const family = css.transitionProperty.split(",").map((property) => property.trim());
    const times = css.transitionDuration.split(",").map((time) => Number.parseFloat(time));
    return (
      family.some(
        (property, index) => ["all", "opacity"].includes(property) && (times[index % times.length] ?? 0) > 0,
      ) ||
      (node.getAnimations?.() ?? []).some(
        (handle) =>
          handle !== animation &&
          (handle.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "opacity" in frame),
      )
    );
  };
  const play = (from?: string, forceImmediate = false) => {
    const input = current;
    if (!alive || !input) return;
    const parameters = input.cm.parameters(
      input.present
        ? bindMotionParameters(presenceInline, "data.transition/opacity")
        : bindMotionParameters(presenceExit, "exit.fade/opacity"),
    );
    if (parameters.kind !== "visual") return;
    const clock = parameters.opacity;
    const immediate = forceImmediate || blocked || clock.duration === 0;
    if (
      (immediate && input.present) ||
      !node.isConnected ||
      typeof node.animate !== "function" ||
      (input.present && node.contains(node.ownerDocument.activeElement))
    ) {
      settle();
      return;
    }
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    if (!css || css.display === "none" || css.visibility === "hidden") {
      settle();
      return;
    }
    if (callerOpacity(css)) {
      settle();
      return;
    }
    const epoch = ++generation;
    const revision = transaction.revision("presence", input.present, node);
    let handle: Animation | null = null;
    lease = owner.begin(revision, ["opacity"], { collectionVisuals: new Set([node]) }, (settled) => {
      handle?.cancel();
      if (settled && alive && current?.present === false) current.complete?.();
    });
    if (!lease?.current()) return;
    const owned = lease;
    handle = node.animate(
      [{ opacity: from ?? (input.present ? 0 : css.opacity) }, { opacity: input.present ? css.opacity : 0 }],
      {
        duration: motionMilliseconds(immediate ? 0 : Number(clock.duration)),
        delay: motionMilliseconds(immediate ? 0 : Number(clock.delay ?? 0)),
        easing: `cubic-bezier(${input.cm.scope.tokens.ease[input.present ? "out" : "in"].join(",")})`,
        fill: "both",
      },
    );
    animation = handle;
    void handle.finished.then(
      () => {
        if (
          !alive ||
          !node.isConnected ||
          epoch !== generation ||
          !owned.current() ||
          current?.present !== input.present
        )
          return;
        // An independently retained descendant may still be exiting. Keep this
        // finished zero-opacity envelope until unmount/re-entry, rather than
        // exposing the root again while the parent waits for that descendant.
        if (input.present) settle();
        else input.complete?.();
      },
      () => {},
    );
    if (immediate) handle.finish();
  };
  const interact = () => {
    if (current?.present) settle();
  };
  for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
    node.addEventListener(event, interact, true);
  const opacityStyle = () => {
    const style = node.style;
    return JSON.stringify([
      style.opacity,
      style.animation,
      /(?:^|,)\s*(?:all|opacity)\s*(?:,|$)/.test(style.transitionProperty) ? style.transition : "",
      Array.from(style)
        .filter((name) => name.startsWith("--") && !/^--(?:cadence-|motion-|ease-cadence)/.test(name))
        .map((name) => [name, style.getPropertyValue(name)]),
    ]);
  };
  let callerStyle = opacityStyle();
  const observer = new MutationObserver((records) => {
    const next = opacityStyle();
    // Scoped colour clocks and inherited Cadence tokens are another owned
    // family. Only potentially conflicting caller paint revokes this channel.
    if (
      (next !== callerStyle || records.some((record) => record.attributeName !== "style")) &&
      (current?.present || callerOpacity())
    )
      settle();
    callerStyle = next;
  });
  observer.observe(node, { attributes: true, attributeFilter: ["class", "style", "disabled", "aria-disabled"] });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    blocked = environment.hidden || environment.immediate;
    if (blocked || (environment.reduced && animation && current?.cm.mode === "full")) {
      if (current?.present === false) {
        cancel();
        play(undefined, true);
      } else settle();
    }
  });
  return {
    commit(input: InlinePresenceCommit) {
      const previous = current;
      current = input;
      // Resolve both clocks on every committed policy, including static baselines.
      input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
      input.cm.parameters(bindMotionParameters(presenceExit, "exit.fade/opacity"));
      const change = previous
        ? previous.present !== input.present || (input.present && !Object.is(previous.revision, input.revision))
        : input.enter || !input.present;
      // Reconcile committed caller paint before consuming its mutation records.
      // A replacement may retarget this channel; an unrelated render must not
      // leave an old opacity envelope over a newer caller declaration.
      const nextCallerStyle = opacityStyle();
      const mutations = observer.takeRecords();
      if (!change && (nextCallerStyle !== callerStyle || mutations.some((record) => record.attributeName !== "style")))
        settle();
      callerStyle = nextCallerStyle;
      if (change) {
        const from = animation ? node.ownerDocument.defaultView?.getComputedStyle(node).opacity : undefined;
        cancel();
        play(from);
      } else if (input.cm.disabled || input.cm.timeScale === 0) {
        if (input.present) settle();
        else if (animation?.effect?.getTiming().duration !== 0) {
          cancel();
          play();
        }
      } else if (previous?.cm.mode === "full" && input.cm.reduced && animation) {
        const from = node.ownerDocument.defaultView?.getComputedStyle(node).opacity;
        cancel();
        play(from);
      }
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      observer.disconnect();
      unsubscribe();
      for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
        node.removeEventListener(event, interact, true);
    },
  };
}
